// One fixed diagnostic command. No live stdin, caller command, credential UI or retries.
using System;
using System.IO;
using System.Diagnostics;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using C=HubSshMaintenanceCommon;
using J=HubSshR2DiagnosticJson;
using P=HubSshR2DiagnosticCapsule;
using K=HubSshR2DiagnosticCatalog;
public static class HubSshR2DiagnosticEntry {
  static readonly HashSet<string> Events=new HashSet<string>(("ADMISSION_VERIFIED GRANT_CONSUMED DIAGNOSTIC_RESULT_VALIDATED ASKPASS_SUPPLIED ASKPASS_REJECTED SSH_HOST_PIN_MATCHED SSH_PASSWORD_AUTHENTICATED SSH_PERMISSION_DENIED SSH_INPUT_FAILED SSH_OUTPUT_FAILED SSH_DIAGNOSTIC_REJECTED SSH_DEADLINE").Split(' '));
  public static void Event(string name){if(name.StartsWith("SSH_PID:",StringComparison.Ordinal))return;C.Require(Events.Contains(name),"DIAGNOSTIC_EVENT_REJECTED");Console.Error.WriteLine("HUB_R2_DIAGNOSTIC_EVENT:"+name);Console.Error.Flush();}
  public static int Fail(Exception error){string code=error is InvalidOperationException&&Regex.IsMatch(error.Message,"^[A-Z0-9_]{1,100}$")?error.Message:"DIAGNOSTIC_"+error.GetType().Name.ToUpperInvariant()+"_"+error.HResult.ToString("X8");Console.WriteLine(C.Canon(new Dictionary<string,object>{{"ok",false},{"code",code}}));return 125;}
  static int Budget(Dictionary<string,object> grant,Stopwatch timer){long elapsed=(timer.ElapsedTicks*1000+Stopwatch.Frequency-1)/Stopwatch.Frequency;long utcTicks=DateTime.UtcNow.Ticks-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).Ticks;long expiry=(long)(int)grant["expiresAt"]*1000-(utcTicks+9999)/10000;return checked((int)Math.Max(0,Math.Min(45000-elapsed,expiry)));}
  static byte[] FixedInput(Dictionary<string,object> grant){byte[] payload=Convert.FromBase64String(K.PayloadBase64);C.Require(payload.Length==K.PayloadLength&&C.Hash(payload)==K.PayloadSHA256&&K.DeadlineMs==45000,"DIAGNOSTIC_EMBEDDED_PAYLOAD_CHANGED");var request=new Dictionary<string,object>{{"protocol",1},{"op","inspect-r2-run-v1"},{"sequence",1},{"nonce",P.RunNonce},{"originalCatalogSHA256",P.OriginalCatalogSHA256},{"uid",P.Uid},{"bootId",P.BootId},{"expiresAtUnixSeconds",grant["expiresAt"]}};byte[] encoded=C.Utf8.GetBytes(C.Canon(request));C.Require(encoded.Length<=4096,"DIAGNOSTIC_REQUEST_BOUND");byte[] input=new byte[payload.Length+4+encoded.Length];Buffer.BlockCopy(payload,0,input,0,payload.Length);int n=encoded.Length;input[payload.Length]=(byte)(n>>24);input[payload.Length+1]=(byte)(n>>16);input[payload.Length+2]=(byte)(n>>8);input[payload.Length+3]=(byte)n;Buffer.BlockCopy(encoded,0,input,payload.Length+4,n);return input;}
  [STAThread] public static int Main(string[] args){if(Environment.GetEnvironmentVariable("HUB_SSH_VAULT_PIPE")!=null)return HubSshR2DiagnosticTransport.Askpass();var timer=Stopwatch.StartNew();byte[] secret=null,input=null,output=null;try{
    C.Require(args.Length==0,"DIAGNOSTIC_ARGUMENTS_REJECTED");string encoded=Environment.GetEnvironmentVariable("HUB_SSH_R2_DIAGNOSTIC_REQUEST");Environment.SetEnvironmentVariable("HUB_SSH_R2_DIAGNOSTIC_REQUEST",null);C.Require(encoded!=null&&encoded.Length<=28000,"DIAGNOSTIC_REQUEST_BOUND");byte[] requestBytes=Convert.FromBase64String(encoded);C.Require(Convert.ToBase64String(requestBytes)==encoded,"DIAGNOSTIC_REQUEST_ENCODING");var request=J.Parse(C.Utf8.GetString(requestBytes),21000,true);C.Fields(request,"mode","grant");C.Require(C.Str(request,"mode",32)=="inspect-r2-run-v1","DIAGNOSTIC_OPERATION_REJECTED");var grant=J.Object(request,"grant");
    using(var state=new HubSshR2DiagnosticState(grant)){
      Event("ADMISSION_VERIFIED");input=FixedInput(grant);C.Require(Budget(grant,timer)>=8000,"DIAGNOSTIC_DEADLINE");state.Consume();Event("GRANT_CONSUMED");C.Require(Budget(grant,timer)>=8000,"DIAGNOSTIC_DEADLINE");secret=state.ReadSecret();state.Fresh();int remaining=Budget(grant,timer);C.Require(remaining>=8000,"DIAGNOSTIC_DEADLINE");var d=state.Destination;
      var result=HubSshR2DiagnosticTransport.Run(new HubSshR2DiagnosticTransport.Options{Ssh=(string)d["ssh"],Args=C.Args(d,K.Command),Cwd=(string)d["root"],Helper=C.Self,Secret=secret,FixedInput=input,CaptureOutput=true,DeadlineMs=remaining,ExpiresAtUnixSeconds=(int)grant["expiresAt"],HostFingerprint=(string)d["hostFingerprint"],EventSink=Event});
      output=result.Output;C.Require(timer.ElapsedMilliseconds<=45000,"DIAGNOSTIC_DEADLINE");C.Require(result.CleanupVerified,"DIAGNOSTIC_LOCAL_CLEANUP_UNVERIFIED");C.Require(result.Authenticated&&result.AskpassSupplied,"DIAGNOSTIC_AUTHENTICATION_UNVERIFIED");C.Require(result.ExitCode==0||result.ExitCode==1,"DIAGNOSTIC_SSH_FAILED");var diagnostic=HubSshR2DiagnosticOutput.Frame(output);C.Require((bool)diagnostic["ok"]==(result.ExitCode==0),"DIAGNOSTIC_EXIT_RESULT_MISMATCH");Event("DIAGNOSTIC_RESULT_VALIDATED");
      string response=J.Canon(new Dictionary<string,object>{{"ok",true},{"state","diagnostic-result"},{"grantId",grant["grantId"]},{"runNonce",P.RunNonce},{"diagnostic",diagnostic}});C.Require(C.Utf8.GetByteCount(response)<=135168,"DIAGNOSTIC_OUTPUT_BOUND");C.Require(Budget(grant,timer)>0,"DIAGNOSTIC_DEADLINE");Console.WriteLine(response);return 0;
    }
  }catch(Exception error){return Fail(error);}finally{if(secret!=null)Array.Clear(secret,0,secret.Length);if(input!=null)Array.Clear(input,0,input.Length);if(output!=null)Array.Clear(output,0,output.Length);}}
}
public static class HubSshR2DiagnosticOutput {
  static readonly string[] Names={"intent.json","runtime.json","unit.json","service-kernel.json","execution-gate.json","service-error.json","measurement.json","result.json","closed.json","active.json"};
  static readonly HashSet<string> Statuses=Set("valid missing rejected changed unread unknown");
  static readonly HashSet<string> Codes=Set("OK NOT_READ MISSING JSON_REJECTED SCHEMA_REJECTED BINDING_REJECTED METADATA_REJECTED IDENTITY_CHANGED CONTENT_CHANGED SIZE_BOUND TOTAL_BOUND IO_REJECTED LINUX_REQUIRED ROOT_REJECTED DEADLINE REQUEST_REJECTED REQUEST_EXPIRED BOOT_REJECTED UID_REJECTED RECEIPT_REJECTED LEASE_REJECTED RUNTIME_REJECTED TOOL_FAILED TOOL_OUTPUT_BOUND UNIT_REJECTED UNIT_MISSING SAVED_IDENTITY_UNAVAILABLE UNIT_IDENTITY_CHANGED CGROUP_REJECTED CGROUP_MISSING CGROUP_IDENTITY_CHANGED INSPECTION_FAILED PARTIAL OUTPUT_REJECTED");
  static readonly HashSet<string> RecordedCodes=Set("R2_UNIT_IDENTITY_CHANGED R2_OPERATION_FAILED R2_SERVICE_FAILED R2_BOOT_CHANGED R2_CAPABILITIES_REJECTED R2_CASE_FAILED R2_CGROUP_EVENTS_REJECTED R2_CGROUP_IDENTITY_CHANGED R2_CGROUP_IDENTITY_REJECTED R2_CGROUP_PATH_CHANGED R2_CGROUP_V2_REQUIRED R2_CLEANUP_UNKNOWN R2_CONTROLLER_DISCONNECTED R2_CONTROLLER_NOT_READING R2_DIRECTORY_CHANGED R2_DIRECTORY_OWNER_REJECTED R2_EXECUTION_GATE_EXPIRED R2_EXECUTION_GATE_REJECTED R2_EXTRA_FD_REJECTED R2_FILE_CHANGED R2_FILE_METADATA_REJECTED R2_FILE_OWNER_REJECTED R2_FORBIDDEN_PATH_VISIBLE R2_KERNEL_GATE_BINDING_REJECTED R2_KERNEL_GATE_UNAVAILABLE R2_KERNEL_LIMITS_REJECTED R2_MEASUREMENT_REJECTED R2_NAMESPACE_REJECTED R2_NETWORK_NAMESPACE_REJECTED R2_PARENT_DEATH_GUARD_FAILED R2_PARENT_IDENTITY_REJECTED R2_READONLY_RUNTIME_REJECTED R2_REMOTE_DEADLINE R2_RESULT_PERSISTENCE_FAILED R2_RUNTIME_CHANGED R2_RUNTIME_LINK_ESCAPED R2_RUNTIME_OWNER_REJECTED R2_RUNTIME_PATH_REJECTED R2_RUNTIME_TYPE_REJECTED R2_SANDBOX_DEADLINE R2_SANDBOX_FAILED R2_SANDBOX_OUTPUT_BOUND R2_SANDBOX_RESULT_REJECTED R2_SANDBOX_UID_REJECTED R2_SERVICE_BINDING_REJECTED R2_SERVICE_COMMAND_REJECTED R2_SERVICE_CONFIGURATION_REJECTED R2_SERVICE_EXECUTABLE_REJECTED R2_SERVICE_INTENT_CHANGED R2_SERVICE_INVOCATION_REJECTED R2_SERVICE_PROCESS_REJECTED R2_SERVICE_PROCESS_REUSED R2_SERVICE_PROGRAM_BOUND R2_SERVICE_ROOT_CHANGED R2_SYNTHETIC_READBACK R2_SYNTHETIC_WRITE R2_SYSTEMD_OUTPUT_BOUND R2_SYSTEMD_PROPERTIES_REJECTED R2_SYSTEMD_QUERY_FAILED R2_TMPFS_LIMIT_REJECTED R2_TOOL_DEADLINE R2_TOOL_OUTPUT_BOUND R2_UNIT_IDENTITY_UNAVAILABLE R2_UNIT_KILL_FAILED R2_UNIT_START_FAILED R2_UNIT_STOP_FAILED R2_WRITE_FAILED R2_WRITE_READBACK_REJECTED R2_CREATE_ONLY_PUBLICATION_FAILED R2_CREATE_ONLY_TARGET_EXISTS R2_CREATE_INPUT_REJECTED R2_ATOMIC_PUBLICATION_UNAVAILABLE");
  static HashSet<string> Set(string words){return new HashSet<string>(words.Split(' '),StringComparer.Ordinal);}
  static void Member(object value,HashSet<string> allowed,bool nullable){C.Require((nullable&&value==null)||(value is string&&allowed.Contains((string)value)),"DIAGNOSTIC_OUTPUT_ENUM");}
  static void Boolean(object value,bool nullable){C.Require((nullable&&value==null)||value is bool,"DIAGNOSTIC_OUTPUT_BOOLEAN");}
  static void Number(object value,long min,long max,bool nullable){if(nullable&&value==null)return;C.Require(value is int||value is long,"DIAGNOSTIC_OUTPUT_INTEGER");long number=value is int?(int)value:(long)value;C.Require(number>=min&&number<=max,"DIAGNOSTIC_OUTPUT_INTEGER");}
  static void Hex(object value,int length){C.Require(value==null||(value is string&&Regex.IsMatch((string)value,"^[a-f0-9]{"+length+"}$")),"DIAGNOSTIC_OUTPUT_DIGEST");}
  public static Dictionary<string,object> Frame(byte[] bytes){C.Require(bytes!=null&&bytes.Length>=5&&bytes.Length<=131072,"DIAGNOSTIC_OUTPUT_FRAME_BOUND");uint length=((uint)bytes[0]<<24)|((uint)bytes[1]<<16)|((uint)bytes[2]<<8)|bytes[3];C.Require(length==bytes.Length-4,"DIAGNOSTIC_OUTPUT_FRAME_LENGTH");var result=J.Parse(C.Utf8.GetString(bytes,4,(int)length),131068,true);Validate(result);return result;}
  public static void Validate(Dictionary<string,object> v){C.Fields(v,"protocol","op","sequence","nonce","uid","bootId","ok","code","records","unit","cgroup","cleanupHistorical","providerReady","snapshotAtomic");C.Num(v,"protocol",1,1);C.Num(v,"sequence",1,1);C.Num(v,"uid",P.Uid,P.Uid);C.Require(C.Str(v,"op",32)=="inspection-result"&&C.Str(v,"nonce",64)==P.RunNonce&&C.Str(v,"bootId",36)==P.BootId&&C.Str(v,"cleanupHistorical",16)=="unknown","DIAGNOSTIC_OUTPUT_BINDING");J.Bool(v,"providerReady",false);J.Bool(v,"snapshotAtomic",false);Boolean(v["ok"],false);Member(v["code"],Codes,false);
    object[] records=J.Array(v,"records",10);C.Require(records.Length==10,"DIAGNOSTIC_OUTPUT_RECORD_COUNT");for(int i=0;i<records.Length;i++){var r=records[i] as Dictionary<string,object>;C.Fields(r,"name","status","code","sha256","facts");C.Require(C.Str(r,"name",32)==Names[i],"DIAGNOSTIC_OUTPUT_RECORD_NAME");Member(r["status"],Statuses,false);Member(r["code"],Codes,false);Hex(r["sha256"],64);var f=J.Object(r,"facts");C.Fields(f,"bindingMatches","recordedCode","recordedOk","recordedCleanupVerified","completionState","recordedGuardPassed","measurementShapeValid","invocationId","pid","startTicks","cgroupPathSHA256");foreach(string k in new[]{"bindingMatches","recordedOk","recordedCleanupVerified","recordedGuardPassed","measurementShapeValid"})Boolean(f[k],true);Member(f["recordedCode"],RecordedCodes,true);Member(f["completionState"],Set("closed lease-release-pending"),true);Hex(f["invocationId"],32);Hex(f["cgroupPathSHA256"],64);Number(f["pid"],1,9007199254740991L,true);Number(f["startTicks"],1,9007199254740991L,true);}
    var u=J.Object(v,"unit");C.Fields(u,"status","code","loadState","activeState","subState","invocationId","mainPID","execMainCode","execMainStatus","result","savedIdentityMatches");Member(u["status"],Statuses,false);Member(u["code"],Codes,false);Boolean(u["savedIdentityMatches"],false);Member(u["loadState"],Set("loaded not-found error masked stub merged"),true);Member(u["activeState"],Set("active reloading inactive failed activating deactivating maintenance refreshing"),true);Member(u["subState"],Set("dead condition start-pre start start-post running exited reload reload-signal reload-notify stop stop-watchdog stop-sigterm stop-sigkill stop-post final-watchdog final-sigterm final-sigkill failed auto-restart auto-restart-queued cleaning"),true);Member(u["result"],Set("success resources protocol timeout exit-code signal core-dump watchdog start-limit-hit oom-kill exec-condition skip-condition"),true);Hex(u["invocationId"],32);Number(u["mainPID"],0,2147483647,true);Number(u["execMainCode"],0,255,true);Number(u["execMainStatus"],0,255,true);
    var g=J.Object(v,"cgroup");C.Fields(g,"status","code","identityMatches","populated","frozen","memoryMax","memorySwapMax","pidsMax","cpuQuota","cpuPeriod");Member(g["status"],Statuses,false);Member(g["code"],Codes,false);Boolean(g["identityMatches"],false);foreach(string k in new[]{"populated","frozen","memoryMax","memorySwapMax","pidsMax","cpuQuota","cpuPeriod"})Number(g[k],0,k=="populated"||k=="frozen"?1:9007199254740991L,true);
  }
}
